func (this *Modetrade) ParseWsPosition(position any, optionalArgs ...any) any {
	//
	//     {
	//         "symbol":"PERP_ETH_USDC",
	//         "positionQty":3.1408,
	//         "costPosition":5706.51952,
	//         "lastSumUnitaryFunding":0.804,
	//         "sumUnitaryFundingVersion":0,
	//         "pendingLongQty":0.0,
	//         "pendingShortQty":-1.0,
	//         "settlePrice":1816.9,
	//         "averageOpenPrice":1804.51490427,
	//         "unsettledPnl":-2.79856,
	//         "pnl24H":-338.90179488,
	//         "fee24H":4.242423,
	//         "markPrice":1816.2,
	//         "estLiqPrice":0.0,
	//         "version":179967,
	//         "imrwithOrders":0.1,
	//         "mmrwithOrders":0.05,
	//         "mmr":0.05,
	//         "imr":0.1,
	//         "timestamp":1685154032762
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var contract *string = this.SafeString(position, "symbol")
	market = ccxt.MapTyped(this.SafeMarket(contract, market))
	var size *string = this.SafeString(position, "positionQty")
	var side string
	if ccxt.Precise.StringGt(size, "0") {
		side = "long"
	} else {
		side = "short"
	}
	var contractSize *string = this.SafeString(market, "contractSize")
	var markPrice *string = this.SafeString(position, "markPrice")
	var timestamp *int64 = this.SafeInteger(position, "timestamp")
	var entryPrice *string = this.SafeString(position, "averageOpenPrice")
	var unrealisedPnl *string = this.SafeString(position, "unsettledPnl")
	size = ccxt.Precise.StringAbs(size)
	var notional *string = ccxt.Precise.StringMul(size, markPrice)
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      this.SafeString(market, "symbol"),
		"timestamp":                   timestamp,
		"datetime":                    this.Iso8601(timestamp),
		"lastUpdateTimestamp":         nil,
		"initialMargin":               nil,
		"initialMarginPercentage":     nil,
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"entryPrice":                  this.ParseNumber(entryPrice),
		"notional":                    this.ParseNumber(notional),
		"leverage":                    nil,
		"unrealizedPnl":               this.ParseNumber(unrealisedPnl),
		"contracts":                   this.ParseNumber(size),
		"contractSize":                this.ParseNumber(contractSize),
		"marginRatio":                 nil,
		"liquidationPrice":            this.SafeNumber(position, "estLiqPrice"),
		"markPrice":                   this.ParseNumber(markPrice),
		"lastPrice":                   nil,
		"collateral":                  nil,
		"marginMode":                  "cross",
		"marginType":                  nil,
		"side":                        side,
		"percentage":                  nil,
		"hedged":                      nil,
		"stopLossPrice":               nil,
		"takeProfitPrice":             nil,
	})
}

