	//     {
	//         "topic":"balance",
	//         "ts":1651836695254,
	//         "data":{
	//             "balances":{
	//                 "USDC":{
	//                     "holding":5555815.47398272,
	//                     "frozen":0,
	//                     "interest":0,
	//                     "pendingShortQty":0,
	//                     "pendingExposure":0,
